apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/assets/styles.css
+:root{
+  --bg: #F7FAFA;
+  --surface: #FFFFFF;
+  --ink: #1E2324;
+  --muted: #526165;
+  --teal: #02838D;
+  --teal-2: #27B3A5;
+  --mint: #E7F7F5;
+  --line: rgba(2,131,141,0.16);
+  --shadow: 0 12px 30px rgba(16, 24, 24, 0.10);
+  --shadow-soft: 0 10px 22px rgba(16, 24, 24, 0.08);
+  --radius: 18px;
+  --radius-sm: 14px;
+  --amber: #F3A536;
+  --coral: #F46F61;
+  --focus: 0 0 0 3px rgba(39,179,165,0.35);
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
+  color:var(--ink);
+  background:
+    radial-gradient(1000px 520px at 20% -10%, rgba(39,179,165,0.22), transparent 60%),
+    radial-gradient(900px 500px at 90% 0%, rgba(244,111,97,0.10), transparent 55%),
+    var(--bg);
+  line-height:1.55;
+}
+
+a{color:inherit;text-decoration:none}
+a.link{color:var(--teal);font-weight:600}
+a.link:hover{text-decoration:underline}
+.link.subtle{color:rgba(30,35,36,0.70)}
+
+.container{width:min(1140px, calc(100% - 40px)); margin:0 auto}
+
+.sr-only{
+  position:absolute!important; width:1px; height:1px; padding:0; margin:-1px;
+  overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0;
+}
+
+.skip-link{
+  position:absolute; left:12px; top:10px; z-index:9999;
+  padding:10px 12px; border-radius:12px;
+  background:var(--surface); box-shadow:var(--shadow-soft);
+  transform:translateY(-140%);
+}
+.skip-link:focus{transform:translateY(0); outline:none; box-shadow:var(--shadow-soft), var(--focus)}
+
+/* Header */
+.site-header{position:sticky; top:0; z-index:60; backdrop-filter:saturate(130%) blur(10px)}
+.topbar{background:rgba(247,250,250,0.75); border-bottom:1px solid rgba(0,0,0,0.06)}
+.topbar__inner{display:flex; align-items:center; justify-content:space-between; gap:18px; padding:14px 0}
+
+.brand{display:flex; align-items:center; gap:12px}
+.brand__mark{
+  width:38px; height:38px; border-radius:14px;
+  background:linear-gradient(135deg, var(--teal), var(--teal-2));
+  box-shadow:0 10px 20px rgba(2,131,141,0.22);
+  position:relative;
+}
+.brand__mark:after{
+  content:"";
+  position:absolute; inset:10px;
+  border-radius:12px;
+  background:rgba(255,255,255,0.88);
+  clip-path:polygon(44% 0, 56% 0, 56% 44%, 100% 44%, 100% 56%, 56% 56%, 56% 100%, 44% 100%, 44% 56%, 0 56%, 0 44%, 44% 44%);
+}
+.brand__name{font-weight:800; letter-spacing:-0.02em}
+.brand__tag{font-size:12px; color:rgba(30,35,36,0.70)}
+
+.topbar__actions{display:flex; align-items:center; gap:14px}
+
+.btn{
+  display:inline-flex; align-items:center; justify-content:center;
+  gap:10px; padding:12px 16px; border-radius:999px;
+  border:1px solid transparent; cursor:pointer;
+  font-weight:700; letter-spacing:-0.01em;
+  background:linear-gradient(135deg, var(--teal), var(--teal-2));
+  color:white; box-shadow:0 10px 20px rgba(2,131,141,0.20);
+  transition:transform .12s ease, box-shadow .12s ease, background .12s ease;
+}
+.btn:hover{transform:translateY(-1px); box-shadow:0 14px 26px rgba(2,131,141,0.26)}
+.btn:active{transform:translateY(0)}
+.btn:focus{outline:none; box-shadow:0 14px 26px rgba(2,131,141,0.22), var(--focus)}
+.btn--ghost{background:transparent; color:var(--ink); border-color:rgba(0,0,0,0.12); box-shadow:none}
+.btn--ghost:hover{background:rgba(2,131,141,0.08)}
+.btn--cta{background:linear-gradient(135deg, var(--coral), var(--amber)); box-shadow:0 14px 26px rgba(244,111,97,0.22)}
+.btn--cta:hover{box-shadow:0 18px 30px rgba(244,111,97,0.26)}
+.btn--small{padding:10px 14px; font-weight:700}
+
+.nav{background:rgba(255,255,255,0.75); border-bottom:1px solid rgba(0,0,0,0.06)}
+.nav__inner{display:flex; align-items:center; gap:18px; padding:12px 0}
+.nav__items{display:flex; align-items:center; gap:6px; flex:1; min-width:0}
+.nav__item{
+  appearance:none; border:0; background:transparent; cursor:pointer;
+  padding:10px 12px; border-radius:999px;
+  font-weight:700; color:rgba(30,35,36,0.86);
+  transition:background .12s ease, color .12s ease;
+}
+.nav__item:hover{background:rgba(2,131,141,0.08); color:var(--ink)}
+.nav__item[aria-expanded="true"]{background:rgba(2,131,141,0.12); color:var(--ink)}
+.nav__item:focus{outline:none; box-shadow:var(--focus)}
+
+.nav__search{display:flex; justify-content:flex-end}
+.nav__search input{
+  width:min(360px, 38vw); min-width:180px;
+  padding:11px 12px; border-radius:999px;
+  border:1px solid rgba(0,0,0,0.10);
+  background:rgba(247,250,250,0.70);
+  font:inherit;
+}
+.nav__search input:focus{outline:none; box-shadow:var(--focus); border-color:rgba(2,131,141,0.35)}
+
+.nav__burger{
+  display:none; width:44px; height:44px; border-radius:999px;
+  border:1px solid rgba(0,0,0,0.12); background:rgba(255,255,255,0.9);
+  align-items:center; justify-content:center; gap:4px; cursor:pointer;
+}
+.nav__burger span{display:block; width:18px; height:2px; background:rgba(30,35,36,0.80); border-radius:999px}
+
+/* Mega menu */
+.mega{display:none; position:absolute; left:0; right:0; top:100%; background:rgba(255,255,255,0.92); border-bottom:1px solid rgba(0,0,0,0.06)}
+.mega.is-open{display:block}
+.mega__inner{display:grid; grid-template-columns:1fr 280px; gap:18px; padding:18px 0 22px}
+.mega__panel{display:none}
+.mega__panel.is-active{display:block}
+.mega__title{font-weight:800; letter-spacing:-0.02em; margin-bottom:10px}
+.mega__grid{display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:10px}
+.mega__grid--two{grid-template-columns:repeat(2, minmax(0, 1fr))}
+.mega__link{
+  padding:10px 10px; border-radius:14px;
+  background:rgba(247,250,250,0.85); border:1px solid rgba(2,131,141,0.10);
+  transition:transform .12s ease, box-shadow .12s ease, background .12s ease;
+  font-weight:650; color:rgba(30,35,36,0.86);
+}
+.mega__link:hover{transform:translateY(-1px); box-shadow:var(--shadow-soft); background:rgba(231,247,245,0.9)}
+.mega__link--accent{border-color:rgba(244,111,97,0.24); background:rgba(244,111,97,0.06)}
+
+.mega__aside{display:flex}
+.mega__card{
+  background:linear-gradient(180deg, rgba(2,131,141,0.10), rgba(255,255,255,0.85));
+  border:1px solid rgba(2,131,141,0.16);
+  border-radius:var(--radius);
+  padding:16px;
+  box-shadow:var(--shadow-soft);
+  height:100%;
+}
+.mega__aside-title{font-weight:800; margin-top:10px; letter-spacing:-0.02em}
+.mega__aside-body{color:rgba(30,35,36,0.72); margin:8px 0 14px}
+
+/* Credibility ticker */
+.ticker{background:linear-gradient(90deg, rgba(2,131,141,0.16), rgba(39,179,165,0.12)); border-bottom:1px solid rgba(2,131,141,0.16)}
+.ticker__track{display:flex; align-items:center; gap:16px; padding:10px 0; width:max-content; will-change:transform}
+.ticker__item{font-weight:750; color:rgba(30,35,36,0.86)}
+.ticker__dot{width:6px; height:6px; border-radius:99px; background:rgba(244,111,97,0.82)}
+
+/* Common type */
+.h2{font-size:28px; margin:0; letter-spacing:-0.03em}
+.h3{font-size:18px; margin:0; letter-spacing:-0.02em}
+.lead{font-size:16px; margin:8px 0 0; color:rgba(30,35,36,0.78)}
+.muted{color:rgba(30,35,36,0.68)}
+.note{font-size:13px; color:rgba(30,35,36,0.62); margin:12px 0 0}
+
+.pill{
+  display:inline-flex; align-items:center;
+  padding:6px 10px; border-radius:999px;
+  background:rgba(2,131,141,0.12);
+  border:1px solid rgba(2,131,141,0.20);
+  color:rgba(2,131,141,0.95);
+  font-weight:800; font-size:12px;
+}
+.pill--mint{background:rgba(39,179,165,0.14); border-color:rgba(39,179,165,0.25); color:rgba(2,131,141,0.95)}
+.pill--trust{background:rgba(243,165,54,0.14); border-color:rgba(243,165,54,0.25); color:rgba(150,80,0,0.95)}
+
+.badge{display:inline-flex; align-items:center; gap:10px; font-weight:800; font-size:12px; color:rgba(30,35,36,0.78)}
+.badge__ring{width:12px; height:12px; border-radius:999px; background:conic-gradient(from 0deg, var(--coral), var(--amber), var(--teal-2), var(--coral)); box-shadow:0 0 0 3px rgba(0,0,0,0.04)}
+
+.dot{width:8px; height:8px; border-radius:999px; display:inline-block}
+.dot--teal{background:var(--teal-2)}
+.dot--amber{background:var(--amber)}
+.meta-chip{display:inline-flex; align-items:center; gap:10px; padding:8px 12px; border-radius:999px; border:1px solid rgba(0,0,0,0.10); background:rgba(255,255,255,0.75); font-weight:700; color:rgba(30,35,36,0.78)}
+
+/* Sections */
+.hero{padding:26px 0 18px}
+.hero__grid{display:grid; grid-template-columns:1.5fr 0.9fr; gap:18px; align-items:stretch}
+
+.hero-card{
+  background:linear-gradient(180deg, rgba(255,255,255,0.82), rgba(255,255,255,0.95));
+  border:1px solid rgba(2,131,141,0.16);
+  border-radius:calc(var(--radius) + 6px);
+  padding:22px;
+  box-shadow:var(--shadow);
+  position:relative;
+  overflow:hidden;
+}
+.hero-card:before{
+  content:"";
+  position:absolute; inset:-120px -160px auto auto;
+  width:380px; height:380px;
+  background:radial-gradient(circle at 30% 30%, rgba(39,179,165,0.38), transparent 62%);
+  transform:rotate(8deg);
+}
+.hero-card__top{display:flex; align-items:center; justify-content:space-between; gap:12px; position:relative}
+.hero-card__title{font-size:38px; margin:14px 0 10px; line-height:1.12; letter-spacing:-0.04em; position:relative}
+.hero-card__sub{margin:0; font-size:16px; color:rgba(30,35,36,0.78); position:relative}
+.hero-card__meta{display:flex; gap:10px; flex-wrap:wrap; margin-top:16px; position:relative}
+.hero-card__cta{display:flex; gap:10px; margin-top:18px; flex-wrap:wrap; position:relative}
+
+.trending .card{height:100%}
+.card{background:rgba(255,255,255,0.90); border:1px solid rgba(0,0,0,0.08); border-radius:var(--radius); padding:16px; box-shadow:var(--shadow-soft)}
+.card--soft{background:rgba(255,255,255,0.80)}
+.card--gradient{background:linear-gradient(180deg, rgba(231,247,245,0.82), rgba(255,255,255,0.96)); border-color:rgba(39,179,165,0.22)}
+.card__header{display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:10px}
+
+.trending__list{list-style:none; padding:0; margin:0; display:grid; gap:10px}
+.trending__item{padding:12px; border-radius:16px; background:rgba(247,250,250,0.85); border:1px solid rgba(2,131,141,0.10)}
+.trending__link{display:block; margin-top:8px; font-weight:800; letter-spacing:-0.02em; line-height:1.25}
+.trending__link:hover{text-decoration:underline}
+.tag{display:inline-flex; align-items:center; padding:5px 10px; border-radius:999px; font-size:12px; font-weight:800; border:1px solid transparent}
+.tag--teal{background:rgba(2,131,141,0.12); color:rgba(2,131,141,0.98); border-color:rgba(2,131,141,0.20)}
+.tag--mint{background:rgba(39,179,165,0.14); color:rgba(2,131,141,0.98); border-color:rgba(39,179,165,0.25)}
+.tag--slate{background:rgba(82,97,101,0.12); color:rgba(30,35,36,0.82); border-color:rgba(82,97,101,0.18)}
+.tag--coral{background:rgba(244,111,97,0.14); color:rgba(160,55,45,0.96); border-color:rgba(244,111,97,0.22)}
+
+.newsletter{padding:18px 0 8px}
+.newsletter__inner{
+  display:grid; grid-template-columns:1.2fr 0.8fr; gap:16px; align-items:center;
+  border-radius:calc(var(--radius) + 8px);
+  background:linear-gradient(135deg, rgba(2,131,141,0.14), rgba(244,111,97,0.08));
+  border:1px solid rgba(2,131,141,0.16);
+  box-shadow:var(--shadow);
+  padding:20px;
+}
+.newsletter__form{display:grid; grid-template-columns:1fr auto; gap:10px; align-items:start}
+.newsletter__form input{
+  padding:14px 14px; border-radius:16px; border:1px solid rgba(0,0,0,0.10);
+  background:rgba(255,255,255,0.92); font:inherit;
+}
+.newsletter__form input:focus{outline:none; box-shadow:var(--focus); border-color:rgba(2,131,141,0.35)}
+.form-hint{grid-column:1 / -1; margin:0; font-size:13px; color:rgba(30,35,36,0.70)}
+.form-hint.is-success{color:rgba(2,131,141,0.95)}
+.form-hint.is-error{color:rgba(160,55,45,0.96)}
+
+.topics{padding:22px 0 10px}
+.section-head{display:flex; align-items:flex-end; justify-content:space-between; gap:14px; margin-bottom:12px}
+.section-head__actions{display:flex; align-items:center; gap:14px}
+.carousel-actions{display:flex; align-items:center; gap:8px}
+.icon-btn{
+  width:42px; height:42px; border-radius:999px; cursor:pointer;
+  border:1px solid rgba(0,0,0,0.10); background:rgba(255,255,255,0.85);
+  font-size:22px; line-height:0; color:rgba(30,35,36,0.86);
+  transition:transform .12s ease, background .12s ease;
+}
+.icon-btn:hover{transform:translateY(-1px); background:rgba(231,247,245,0.85)}
+.icon-btn:focus{outline:none; box-shadow:var(--focus)}
+
+.topics__rail{
+  display:flex; gap:12px;
+  overflow:auto; scroll-behavior:smooth; padding:8px 2px 14px;
+  scrollbar-width:thin;
+}
+.topic{
+  min-width:170px; max-width:170px;
+  padding:14px; border-radius:var(--radius);
+  background:rgba(255,255,255,0.90);
+  border:1px solid rgba(2,131,141,0.14);
+  box-shadow:var(--shadow-soft);
+  display:flex; flex-direction:column; gap:10px;
+  transition:transform .12s ease;
+}
+.topic:hover{transform:translateY(-2px)}
+.topic__img{
+  width:66px; height:66px; border-radius:999px;
+  background:radial-gradient(circle at 30% 30%, rgba(39,179,165,0.42), rgba(2,131,141,0.12));
+  position:relative;
+  border:1px solid rgba(2,131,141,0.16);
+}
+.topic__img:after{content:""; position:absolute; inset:14px; border-radius:999px; background:rgba(255,255,255,0.82)}
+.topic__label{font-weight:800; letter-spacing:-0.02em; line-height:1.15}
+.topic__img[data-img="heart"]{background:radial-gradient(circle at 30% 30%, rgba(244,111,97,0.30), rgba(2,131,141,0.12))}
+.topic__img[data-img="mind"]{background:radial-gradient(circle at 30% 30%, rgba(243,165,54,0.25), rgba(2,131,141,0.12))}
+.topic__img[data-img="gut"]{background:radial-gradient(circle at 30% 30%, rgba(39,179,165,0.34), rgba(2,131,141,0.12))}
+.topic__img[data-img="warm"]{background:radial-gradient(circle at 30% 30%, rgba(244,111,97,0.22), rgba(243,165,54,0.12))}
+.topic__img[data-img="glucose"]{background:radial-gradient(circle at 30% 30%, rgba(39,179,165,0.30), rgba(243,165,54,0.14))}
+.topic__img[data-img="scale"]{background:radial-gradient(circle at 30% 30%, rgba(2,131,141,0.30), rgba(39,179,165,0.14))}
+
+.tools{padding:18px 0 10px}
+.tools__grid{display:grid; grid-template-columns:1.15fr 0.85fr; gap:16px}
+.mini-list{display:grid; gap:10px; margin-top:14px}
+.mini{padding:12px; border-radius:16px; background:rgba(255,255,255,0.82); border:1px solid rgba(2,131,141,0.12)}
+.mini__title{font-weight:850; letter-spacing:-0.02em}
+.mini__body{color:rgba(30,35,36,0.68); font-size:13px; margin-top:4px}
+
+.tool-cards{display:grid; gap:10px}
+.tool{display:grid; grid-template-columns:56px 1fr; gap:12px; padding:12px; border-radius:16px; border:1px solid rgba(0,0,0,0.08); background:rgba(247,250,250,0.80); transition:transform .12s ease, box-shadow .12s ease}
+.tool:hover{transform:translateY(-1px); box-shadow:var(--shadow-soft)}
+.tool__icon{width:56px; height:56px; border-radius:16px; display:flex; align-items:center; justify-content:center; font-weight:900; background:linear-gradient(135deg, rgba(2,131,141,0.16), rgba(39,179,165,0.12)); border:1px solid rgba(2,131,141,0.14)}
+.tool__title{font-weight:900; letter-spacing:-0.02em}
+.tool__body{color:rgba(30,35,36,0.68); font-size:13px; margin-top:3px}
+.tool__cta{margin-top:8px; color:var(--teal); font-weight:900}
+
+.recommended{padding:18px 0 10px}
+.tabs{display:flex; flex-wrap:wrap; gap:8px; margin:10px 0 14px}
+.tab{
+  border:1px solid rgba(0,0,0,0.10); background:rgba(255,255,255,0.82);
+  padding:10px 12px; border-radius:999px; cursor:pointer;
+  font-weight:850; color:rgba(30,35,36,0.80);
+  transition:background .12s ease, transform .12s ease;
+}
+.tab:hover{transform:translateY(-1px); background:rgba(231,247,245,0.85)}
+.tab.is-active{background:rgba(2,131,141,0.14); border-color:rgba(2,131,141,0.22); color:rgba(2,131,141,0.98)}
+.tab:focus{outline:none; box-shadow:var(--focus)}
+
+.grid{display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:14px}
+.article{
+  border-radius:var(--radius);
+  background:rgba(255,255,255,0.90);
+  border:1px solid rgba(0,0,0,0.08);
+  box-shadow:var(--shadow-soft);
+  padding:14px;
+  display:flex; flex-direction:column; gap:10px;
+  min-height:164px;
+}
+.article__top{display:flex; align-items:center; justify-content:space-between; gap:10px}
+.article__title{font-weight:900; letter-spacing:-0.02em; line-height:1.2}
+.article__meta{display:flex; gap:8px; flex-wrap:wrap; color:rgba(30,35,36,0.66); font-size:12px}
+.chip{padding:4px 10px; border-radius:999px; border:1px solid rgba(0,0,0,0.10); background:rgba(247,250,250,0.78); font-weight:800}
+.article__footer{margin-top:auto; display:flex; align-items:center; justify-content:space-between; gap:12px}
+.readmore{color:var(--teal); font-weight:900}
+
+.trust{padding:18px 0 10px}
+.trust__head{display:flex; align-items:flex-end; justify-content:space-between; gap:14px; margin-bottom:12px}
+.trust__badge{
+  min-width:260px;
+  border-radius:var(--radius);
+  padding:14px;
+  background:linear-gradient(135deg, rgba(243,165,54,0.14), rgba(2,131,141,0.10));
+  border:1px solid rgba(243,165,54,0.20);
+  box-shadow:var(--shadow-soft);
+}
+.trust__badge-title{font-weight:900}
+.trust__badge-body{color:rgba(30,35,36,0.70); font-size:13px; margin-top:6px}
+.trust__grid{display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:12px}
+.trust-card{
+  border-radius:var(--radius);
+  background:rgba(255,255,255,0.90);
+  border:1px solid rgba(2,131,141,0.14);
+  box-shadow:var(--shadow-soft);
+  padding:14px;
+}
+.trust-card__icon{width:42px; height:42px; border-radius:14px; display:flex; align-items:center; justify-content:center; background:rgba(231,247,245,0.85); border:1px solid rgba(2,131,141,0.14); margin-bottom:10px}
+.trust-card p{margin:8px 0 0; color:rgba(30,35,36,0.72)}
+
+.programs,.videos{padding:18px 0 10px}
+.cards{display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:12px}
+.card-link{
+  border-radius:var(--radius);
+  overflow:hidden;
+  border:1px solid rgba(0,0,0,0.08);
+  background:rgba(255,255,255,0.92);
+  box-shadow:var(--shadow-soft);
+  transition:transform .12s ease;
+}
+.card-link:hover{transform:translateY(-2px)}
+.card-link__media{height:92px; background:linear-gradient(135deg, rgba(2,131,141,0.18), rgba(39,179,165,0.08))}
+.card-link__media[data-grad="skin"]{background:linear-gradient(135deg, rgba(244,111,97,0.16), rgba(2,131,141,0.10))}
