+.tool__icon{width:56px; height:56px; border-radius:16px; display:flex; align-items:center; justify-content:center; font-weight:900; background:linear-gradient(135deg, rgba(2,131,141,0.16), rgba(39,179,165,0.12)); border:1px solid rgba(2,131,141,0.14)}
+.tool__title{font-weight:900; letter-spacing:-0.02em}
+.tool__body{color:rgba(30,35,36,0.68); font-size:13px; margin-top:3px}
+.tool__cta{margin-top:8px; color:var(--teal); font-weight:900}
+
+.recommended{padding:18px 0 10px}
+.tabs{display:flex; flex-wrap:wrap; gap:8px; margin:10px 0 14px}
+.tab{
+  border:1px solid rgba(0,0,0,0.10); background:rgba(255,255,255,0.82);
+  padding:10px 12px; border-radius:999px; cursor:pointer;
+  font-weight:850; color:rgba(30,35,36,0.80);
+  transition:background .12s ease, transform .12s ease;
