+.tab:hover{transform:translateY(-1px); background:rgba(231,247,245,0.85)}
+.tab.is-active{background:rgba(2,131,141,0.14); border-color:rgba(2,131,141,0.22); color:rgba(2,131,141,0.98)}
+.tab:focus{outline:none; box-shadow:var(--focus)}
+
+.grid{display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:14px}
+.article{
+  border-radius:var(--radius);
+  background:rgba(255,255,255,0.90);
+  border:1px solid rgba(0,0,0,0.08);
+  box-shadow:var(--shadow-soft);
+  padding:14px;
+  display:flex; flex-direction:column; gap:10px;
+  min-height:164px;
+}
+.article__top{display:flex; align-items:center; justify-content:space-between; gap:10px}
+.article__title{font-weight:900; letter-spacing:-0.02em; line-height:1.2}
+.article__meta{display:flex; gap:8px; flex-wrap:wrap; color:rgba(30,35,36,0.66); font-size:12px}
+.chip{padding:4px 10px; border-radius:999px; border:1px solid rgba(0,0,0,0.10); background:rgba(247,250,250,0.78); font-weight:800}
+.article__footer{margin-top:auto; display:flex; align-items:center; justify-content:space-between; gap:12px}
+.readmore{color:var(--teal); font-weight:900}
+
+.trust{padding:18px 0 10px}
+.trust__head{display:flex; align-items:flex-end; justify-content:space-between; gap:14px; margin-bottom:12px}
+.trust__badge{
+  min-width:260px;
+  border-radius:var(--radius);
+  padding:14px;
+  background:linear-gradient(135deg, rgba(243,165,54,0.14), rgba(2,131,141,0.10));
+  border:1px solid rgba(243,165,54,0.20);
+  box-shadow:var(--shadow-soft);
+}
+.trust__badge-title{font-weight:900}
+.trust__badge-body{color:rgba(30,35,36,0.70); font-size:13px; margin-top:6px}
+.trust__grid{display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:12px}
+.trust-card{
+  border-radius:var(--radius);
+  background:rgba(255,255,255,0.90);
+  border:1px solid rgba(2,131,141,0.14);
+  box-shadow:var(--shadow-soft);
+  padding:14px;
+}
+.trust-card__icon{width:42px; height:42px; border-radius:14px; display:flex; align-items:center; justify-content:center; background:rgba(231,247,245,0.85); border:1px solid rgba(2,131,141,0.14); margin-bottom:10px}
+.trust-card p{margin:8px 0 0; color:rgba(30,35,36,0.72)}
+
+.programs,.videos{padding:18px 0 10px}
+.cards{display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:12px}
+.card-link{
+  border-radius:var(--radius);
+  overflow:hidden;
+  border:1px solid rgba(0,0,0,0.08);
+  background:rgba(255,255,255,0.92);
+  box-shadow:var(--shadow-soft);
+  transition:transform .12s ease;
+}
+.card-link:hover{transform:translateY(-2px)}
+.card-link__media{height:92px; background:linear-gradient(135deg, rgba(2,131,141,0.18), rgba(39,179,165,0.08))}
+.card-link__media[data-grad="skin"]{background:linear-gradient(135deg, rgba(244,111,97,0.16), rgba(2,131,141,0.10))}
+.card-link__media[data-grad="ms"]{background:linear-gradient(135deg, rgba(39,179,165,0.20), rgba(243,165,54,0.10))}
+.card-link__media[data-grad="eczema"]{background:linear-gradient(135deg, rgba(243,165,54,0.22), rgba(244,111,97,0.08))}
+.card-link__media[data-grad="mens"]{background:linear-gradient(135deg, rgba(2,131,141,0.20), rgba(82,97,101,0.08))}
+.card-link__body{padding:12px}
+.card-link__title{margin-top:10px; font-weight:950; letter-spacing:-0.02em}
+
+.cards--videos{grid-template-columns:repeat(4, minmax(0, 1fr))}
+.video{display:block; border-radius:var(--radius); overflow:hidden; border:1px solid rgba(0,0,0,0.08); background:rgba(255,255,255,0.92); box-shadow:var(--shadow-soft); transition:transform .12s ease}
+.video:hover{transform:translateY(-2px)}
+.video__thumb{height:108px; background:linear-gradient(135deg, rgba(2,131,141,0.20), rgba(244,111,97,0.10)); display:flex; align-items:center; justify-content:center; position:relative}
+.video__thumb[data-thumb="psoriasis"]{background:linear-gradient(135deg, rgba(243,165,54,0.20), rgba(2,131,141,0.12))}
+.video__thumb[data-thumb="parkinsons"]{background:linear-gradient(135deg, rgba(39,179,165,0.20), rgba(82,97,101,0.10))}
+.video__thumb[data-thumb="urticaria"]{background:linear-gradient(135deg, rgba(244,111,97,0.16), rgba(243,165,54,0.12))}
+.video__thumb[data-thumb="constipation"]{background:linear-gradient(135deg, rgba(2,131,141,0.18), rgba(39,179,165,0.10))}
+.video__play{width:44px; height:44px; border-radius:999px; background:rgba(255,255,255,0.90); border:1px solid rgba(0,0,0,0.10); display:flex; align-items:center; justify-content:center; font-weight:900; box-shadow:var(--shadow-soft)}
+.video__title{padding:12px; font-weight:900; letter-spacing:-0.02em; line-height:1.2}
+
+/* Footer */
+.footer{margin-top:18px; padding:26px 0 16px; border-top:1px solid rgba(0,0,0,0.08); background:rgba(255,255,255,0.75)}
+.brand--footer .brand__mark{width:34px; height:34px}
+.footer__grid{display:grid; grid-template-columns:1.1fr 1fr 1fr; gap:16px; align-items:start}
+.footer__form{display:grid; grid-template-columns:1fr auto; gap:10px}
+.footer__form input{padding:12px 12px; border-radius:14px; border:1px solid rgba(0,0,0,0.10); background:rgba(247,250,250,0.75); font:inherit}
+.footer__form input:focus{outline:none; box-shadow:var(--focus); border-color:rgba(2,131,141,0.35)}
+.footer__links{display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:10px}
+.footer__title{font-weight:950; margin-bottom:8px}
+.footer__col a{display:block; color:rgba(30,35,36,0.70); padding:6px 0}
+.footer__col a:hover{color:var(--ink)}
+.footer__bottom{padding-top:14px}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero__grid{grid-template-columns:1fr;}
+  .tools__grid{grid-template-columns:1fr;}
+  .trust__grid{grid-template-columns:repeat(2, minmax(0, 1fr));}
+  .cards{grid-template-columns:repeat(2, minmax(0, 1fr));}
+  .grid{grid-template-columns:repeat(2, minmax(0, 1fr));}
+  .mega__inner{grid-template-columns:1fr}
+  .mega__aside{display:none}
+  .mega__grid{grid-template-columns:repeat(2, minmax(0, 1fr))}
+}
+
+@media (max-width: 640px){
+  .nav__burger{display:inline-flex}
+  .nav__items{display:none}
+  .nav__items.is-open{display:flex; flex-wrap:wrap}
+  .nav__search{display:none}
+  .newsletter__inner{grid-template-columns:1fr}
+  .grid{grid-template-columns:1fr}
+  .cards{grid-template-columns:1fr}
+  .trust__head{flex-direction:column; align-items:flex-start}
+  .trust__badge{width:100%}
+  .footer__grid{grid-template-columns:1fr;}
+  .footer__links{grid-template-columns:repeat(2, minmax(0, 1fr));}
+}
+
+@media (prefers-reduced-motion: reduce){
+  .ticker__track{transition:none!important}
+  .topics__rail{scroll-behavior:auto}
+  .btn, .tab, .tool, .topic, .card-link, .video{transition:none!important}
+}
+
*** End Patch
PATCH"}

